sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading) {
        return;
    }

    // Keep Eligibility Status read-only
    g_form.setReadOnly('eligibility_status', true);

    var student = g_form.getValue('student');
    var drive = g_form.getValue('drive');

    // If Student or Drive is not selected
    if (!student || !drive) {
        g_form.setValue('eligibility_status', 'Pending');
        return;
    }

    // Call Script Include
    var ga = new GlideAjax('CheckEligibility');

    ga.addParam('sysparm_name', 'checkEligibility');
    ga.addParam('sysparm_student_id', student);
    ga.addParam('sysparm_drive_id', drive);

    ga.getXMLAnswer(function(answer) {

        if (answer) {
            g_form.setValue('eligibility_status', answer);
        }

    });
}
